  "liquid-glass": "precision highp float;\n\n/** @resolution */\nuniform vec2 u_resolution;\n\n/**\n * @label Backdrop\n * @mipmap\n */\nuniform sampler2D u_bg;\n\n/** @sdf */\nuniform sampler2D u_sdf;\n\n/**\n * @label Tint\n * @color\n * @default #FFFFFF\n */\nuniform vec3 u_tint;\n\n/**\n * @label Tint amount\n * @default 0.08\n * @range 0, 1\n */\nuniform float u_tintAmt;\n\n/**\n * @label Bezel width\n * @default 16\n * @range 1, 60\n */\nuniform float u_bezel;\n\n/**\n * @label Refraction\n * @default 22\n * @range 0, 80\n */\nuniform float u_refract;\n\n/**\n * @label Frost (blur radius, px)\n * @default 10\n * @range 0, 40\n */\nuniform float u_frost;\n\n/**\n * @label Highlight\n * @default 0.7\n * @range 0, 1.5\n */\nuniform float u_spec;\n\n/**\n * @label Dispersion\n * @default 0.12\n * @range 0, 0.5\n */\nuniform float u_disp;\n\n/**\n * @label Light from top (1) or bottom (-1)\n * @default 1\n * @range -1, 1\n */\nuniform float u_lightY;\n\n// Frosted backdrop: 16-tap spiral blur, with each color channel bent a little differently.\nvec3 backdrop(vec2 p, vec2 off) {\n  vec3 acc = vec3(0.0);\n  for (int i = 0; i < 16; i++) {\n    float fi = float(i);\n    float a = fi * 2.39996;\n    vec2 tap = vec2(cos(a), sin(a)) * sqrt((fi + 0.5) / 16.0) * u_frost;\n    acc.r += texture2D(u_bg, (p + tap + off * (1.0 + u_disp)) / u_resolution).r;\n    acc.g += texture2D(u_bg, (p + tap + off) / u_resolution).g;\n    acc.b += texture2D(u_bg, (p + tap + off * (1.0 - u_disp)) / u_resolution).b;\n  }\n  return acc / 16.0;\n}\n\nvoid main() {\n  vec2 p = gl_FragCoord.xy;\n  vec4 s = texture2D(u_sdf, p / u_resolution);\n  float d = max(s.r, 0.0);\n  float gl = length(s.gb);\n  vec2 n = gl > 0.0001 ? s.gb / gl : vec2(0.0);\n\n  // Lens: near the edge, pull in light from just outside the shape.\n  float e = clamp(1.0 - d / u_bezel, 0.0, 1.0);\n  float bend = e * e;\n  vec3 col = backdrop(p, -n * bend * u_refract);\n  col = mix(col, u_tint, u_tintAmt);\n\n  // Specular rim: bright on the edge facing the light, softer on the far edge.\n  vec2 L = normalize(vec2(-1.0, u_lightY));\n  float facing = dot(-n, L);\n  float rim = 1.0 - smoothstep(0.0, 1.6, d);\n  float spec = rim * (0.85 * pow(max(facing, 0.0), 1.5) + 0.35 * pow(max(-facing, 0.0), 1.5) + 0.1);\n  float sheen = bend * 0.05 * (0.4 + 0.6 * max(facing, 0.0));\n  col += u_spec * (spec + sheen);\n\n  gl_FragColor = vec4(col, 1.0);\n}\n",
  "matrix": "precision mediump float;\n/** @resolution */\nuniform vec2 u_resolution;\n/** @time */\nuniform float u_time;\n/**\n * @label State color\n * @color\n * @default #FF5CA8\n */\nuniform vec3 u_color;\n/**\n * @label Sparks\n * @color\n * @default #FFFFFF\n */\nuniform vec3 u_spark;\n/**\n * @label Base\n * @color\n * @default #07070A\n */\nuniform vec3 u_base;\n/**\n * @label Strength\n * @default 0.32\n * @range 0, 1\n */\nuniform float u_strength;\n/**\n * @label Speed\n * @default 1\n * @range 0, 3\n */\nuniform float u_speed;\n\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }\nfloat noise(vec2 p) {\n  vec2 i = floor(p);\n  vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);\n}\nfloat fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 4; i++) { v += a * noise(p); p = p * 2.03 + 11.7; a *= 0.5; } return v; }\n\n// Data matrix: a faint dot grid over the whole screen. Data gathers in slow drifting clusters, a few dots flicker\n// like live data, and a soft scan passes diagonally every few seconds, all in the state color (the top line's glyph).\nvoid main() {\n  vec2 fc = gl_FragCoord.xy;\n  vec2 uv = fc / u_resolution;\n  float asp = u_resolution.x / u_resolution.y, t = u_time * u_speed, s = u_strength / 0.32, cs = 9.0;\n  vec2 cell = floor(fc / cs);\n  vec2 d = fc - cell * cs - 0.5 * cs;\n  float pt = 1.0 - smoothstep(0.6, 1.3, max(abs(d.x), abs(d.y)));\n  float field = smoothstep(0.4, 0.8, fbm(cell * 0.05 + vec2(0.0, 0.03 * t)));\n  float wave = pow(0.5 + 0.5 * sin((uv.x * asp * 0.6 + uv.y) * 4.0 - 0.45 * t), 14.0);\n  float h = hash(cell);\n  float ph = 0.7 * t + 13.0 * h;\n  float live = step(0.982, hash(cell + floor(ph))) * (1.0 - fract(ph));\n  vec3 tint = mix(u_color, u_spark * 0.8, step(0.75, hash(cell + 3.1)));\n  vec3 col = u_base + pt * (vec3(0.025 + 0.06 * field) + u_color * wave * (0.12 + 0.35 * field) + tint * live * 0.8) * s;\n  col += u_color * wave * 0.012 * s;\n  vec2 v = uv - 0.5;\n  col *= 1.0 - dot(v, v) * 0.9;\n  col += (hash(fc) - 0.5) * (2.0 / 255.0);\n  gl_FragColor = vec4(col, 1.0);\n}\n",
